import React from "react";
import { FaTrophy, FaProjectDiagram, FaCalendarAlt, FaPalette, FaBolt, FaUserGraduate, FaLeaf } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      {/* PROJECTS */}
      <div className="section">
        <h2>My Projects</h2>

        <div className="projects-grid">

          <div className="project-card">
            <div className="serial">01</div>
            <div className="icon"><FaBolt /></div>
            <h3>EnergyPulse</h3>
            <p className="desc">
              AI-based smart home dashboard with real-time energy monitoring and control system.
            </p>
            <span className="tech">React.js</span>
          </div>

          <div className="project-card">
            <div className="serial">02</div>
            <div className="icon"><FaUserGraduate /></div>
            <h3>Student Portal</h3>
            <p className="desc">
              Full-stack portal for student management with authentication and database handling.
            </p>
            <span className="tech">Spring Boot, MySQL</span>
          </div>

          <div className="project-card">
            <div className="serial">03</div>
            <div className="icon"><FaLeaf /></div>
            <h3>Farm2Fork</h3>
            <p className="desc">
              Farmer-to-consumer platform with smooth product browsing and responsive UI.
            </p>
            <span className="tech">HTML, CSS, JS</span>
          </div>

          <div className="project-card highlight">
            <div className="serial">04</div>
            <div className="icon">🧠</div>
            <h3>Cogni Flow</h3>
            <p className="desc">
              Cognitive learning UI system designed for structured flow and interactive experience.
            </p>
            <span className="tech">HTML, CSS, JS</span>
          </div>

        </div>
      </div>

      {/* ACHIEVEMENTS (BOTTOM SEPARATE SECTION) */}
      <div className="section achievements">
        <h2>Achievements</h2>

        <div className="achievements-grid">

          <div className="achievement-card">
            <div className="icon"><FaTrophy /></div>
            <h3>Hackathons</h3>
            <p>Semifinalist in Smart India Hackathon 2025.</p>
          </div>

          <div className="achievement-card">
            <div className="icon"><FaProjectDiagram /></div>
            <h3>Best Project Award</h3>
            <p>Won for Li-Fi innovation project at conference.</p>
          </div>

          <div className="achievement-card">
            <div className="icon"><FaCalendarAlt /></div>
            <h3>Tech Events</h3>
            <p>Organized Code Crunch coding event.</p>
          </div>

          <div className="achievement-card">
            <div className="icon"><FaPalette /></div>
            <h3>Non-Tech Events</h3>
            <p>Conducted Fun Spin Round successfully.</p>
          </div>

        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .projects-page {
          min-height: 100vh;
          padding: 50px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        h2 {
          font-size: 34px;
          color: #38BDF8;
          margin-bottom: 30px;
        }

        /* PROJECT GRID */
        .projects-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          gap: 22px;
        }

        /* SQUARE CARD */
        .project-card {
          position: relative;
          padding: 22px;
          border-radius: 16px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          box-shadow: 0 0 15px rgba(56,189,248,0.08);
          transition: 0.4s;
          display: flex;
          flex-direction: column;
          gap: 10px;
          min-height: 220px;
        }

        .project-card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 25px rgba(56,189,248,0.3);
          border-color: #38BDF8;
        }

        .serial {
          position: absolute;
          top: 12px;
          right: 14px;
          font-size: 12px;
          color: #94a3b8;
        }

        .icon {
          font-size: 26px;
          color: #38BDF8;
        }

        h3 {
          margin: 0;
          font-size: 18px;
        }

        .desc {
          font-size: 13px;
          color: #cbd5e1;
          line-height: 1.5;
        }

        .tech {
          margin-top: auto;
          font-size: 12px;
          color: #38BDF8;
          font-weight: 600;
        }

        .highlight {
          border: 1px solid #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.15);
        }

        /* ACHIEVEMENTS */
        .achievements {
          margin-top: 80px;
        }

        .achievements-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          gap: 20px;
        }

        .achievement-card {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .achievement-card:hover {
          transform: translateY(-4px);
          box-shadow: 0 0 20px rgba(56,189,248,0.2);
        }

        @media (max-width: 1000px) {
          .projects-grid,
          .achievements-grid {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
